-- Aeta PostgreSQL schema. All monetary values use NUMERIC, never floating point.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE operation_status AS ENUM ('PENDING','PROCESSING','COMPLETED','FAILED','CANCELLED','REJECTED','EXPIRED');
CREATE TYPE order_side AS ENUM ('BUY','SELL'); CREATE TYPE order_type AS ENUM ('MARKET','LIMIT');
CREATE TABLE roles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT UNIQUE NOT NULL);
CREATE TABLE permissions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT UNIQUE NOT NULL);
CREATE TABLE role_permissions(role_id UUID REFERENCES roles,permission_id UUID REFERENCES permissions,PRIMARY KEY(role_id,permission_id));
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role_id UUID REFERENCES roles,referral_code TEXT UNIQUE NOT NULL,kyc_status TEXT NOT NULL DEFAULT 'PENDING',two_factor_secret_encrypted BYTEA,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sessions(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users,refresh_token_hash TEXT NOT NULL,ip INET,user_agent TEXT,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE kyc_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users,full_name_encrypted BYTEA,birth_date_encrypted BYTEA,country CHAR(2),phone_encrypted BYTEA,document_key TEXT,selfie_key TEXT,status TEXT NOT NULL DEFAULT 'PENDING',reviewed_by UUID REFERENCES users,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE assets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),symbol TEXT UNIQUE NOT NULL,name TEXT NOT NULL,precision SMALLINT NOT NULL CHECK(precision BETWEEN 0 AND 18),enabled BOOLEAN DEFAULT true,networks JSONB DEFAULT '[]');
CREATE TABLE wallets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE NOT NULL REFERENCES users,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE wallet_balances(wallet_id UUID REFERENCES wallets,asset_id UUID REFERENCES assets,total NUMERIC(38,18) NOT NULL DEFAULT 0,available NUMERIC(38,18) NOT NULL DEFAULT 0,locked NUMERIC(38,18) NOT NULL DEFAULT 0,CHECK(total=available+locked),PRIMARY KEY(wallet_id,asset_id));
CREATE TABLE markets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING');
CREATE TABLE trading_pairs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),market_id UUID REFERENCES markets,base_asset_id UUID REFERENCES assets,quote_asset_id UUID REFERENCES assets,enabled BOOLEAN DEFAULT false,fee_rate NUMERIC(12,10) NOT NULL DEFAULT 0,UNIQUE(base_asset_id,quote_asset_id));
CREATE TABLE orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users,pair_id UUID REFERENCES trading_pairs,side order_side NOT NULL,type order_type NOT NULL,price NUMERIC(38,18),quantity NUMERIC(38,18) NOT NULL,filled_quantity NUMERIC(38,18) NOT NULL DEFAULT 0,status operation_status NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE trades(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),pair_id UUID REFERENCES trading_pairs,buy_order_id UUID REFERENCES orders,sell_order_id UUID REFERENCES orders,price NUMERIC(38,18) NOT NULL,quantity NUMERIC(38,18) NOT NULL,fee NUMERIC(38,18) NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users,type TEXT NOT NULL,status operation_status NOT NULL,asset_id UUID REFERENCES assets,amount NUMERIC(38,18) NOT NULL,reference_id UUID,idempotency_key TEXT UNIQUE,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE ledger_entries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id UUID NOT NULL REFERENCES transactions,wallet_id UUID NOT NULL REFERENCES wallets,asset_id UUID NOT NULL REFERENCES assets,direction TEXT NOT NULL CHECK(direction IN('DEBIT','CREDIT')),amount NUMERIC(38,18) NOT NULL CHECK(amount>0),balance_after NUMERIC(38,18) NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE deposits(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users,asset_id UUID REFERENCES assets,network TEXT,address TEXT,amount NUMERIC(38,18) NOT NULL,external_tx_id TEXT,status operation_status DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE withdrawals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users,asset_id UUID REFERENCES assets,network TEXT,address TEXT NOT NULL,amount NUMERIC(38,18) NOT NULL,fee NUMERIC(38,18) NOT NULL,status operation_status DEFAULT 'PENDING',approved_by UUID REFERENCES users,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE investment_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,min_amount NUMERIC(38,18),max_amount NUMERIC(38,18),duration_days INT,return_type TEXT,fee_rate NUMERIC(12,10),withdrawal_terms TEXT,active BOOLEAN DEFAULT false,description TEXT,risk TEXT,base_asset_id UUID REFERENCES assets,simulation_only BOOLEAN DEFAULT true);
CREATE TABLE investments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users,plan_id UUID REFERENCES investment_plans,initial_amount NUMERIC(38,18),current_value NUMERIC(38,18),status operation_status,start_at TIMESTAMPTZ,end_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE profit_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),investment_id UUID REFERENCES investments,value NUMERIC(38,18),recorded_at TIMESTAMPTZ DEFAULT now(),simulated BOOLEAN DEFAULT true);
CREATE TABLE referrals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),referrer_id UUID REFERENCES users,referred_id UUID UNIQUE REFERENCES users,reward NUMERIC(38,18) DEFAULT 0,status operation_status DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users,title TEXT NOT NULL,body TEXT NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE support_tickets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users,subject TEXT NOT NULL,body TEXT NOT NULL,status operation_status DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users,action TEXT NOT NULL,ip INET,device TEXT,previous_value JSONB,new_value JSONB,reference_id UUID,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE system_settings(key TEXT PRIMARY KEY,value JSONB NOT NULL,updated_by UUID REFERENCES users,updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX idx_ledger_wallet_asset ON ledger_entries(wallet_id,asset_id,created_at); CREATE INDEX idx_audit_user_time ON audit_logs(user_id,created_at); CREATE INDEX idx_orders_user_status ON orders(user_id,status);
-- Balance mutations must occur in a SERIALIZABLE transaction with matching balanced ledger entries.